mapper.select:
WITH requested(id) AS ( VALUES
(#{id})
), normalized AS ( SELECT DISTINCT id FROM requested ), target_sku AS ( SELECT s.id, s.stock_quantity FROM normalized n INNER JOIN product_sku s ON s.id = n.id WHERE s.spu_id = #{spuId} AND s.status = 'ACTIVE' ), active_hot AS ( SELECT h.sku_id, h.stock_quantity, h.remaining_quantity FROM product_hot_sku h INNER JOIN target_sku s ON s.id = h.sku_id WHERE h.spu_id = #{spuId} AND h.status = 'ENABLED' AND (h.start_at IS NULL OR h.start_at <= #{now}) AND (h.end_at IS NULL OR h.end_at > #{now}) ) SELECT encode(s.id, 'hex') AS "skuId", s.stock_quantity AS "skuStockQuantity", h.stock_quantity AS "hotStockQuantity", h.remaining_quantity AS "hotRemainingQuantity", (h.sku_id IS NOT NULL) AS "hotSku" FROM target_sku s LEFT JOIN active_hot h ON h.sku_id = s.id ORDER BY encode(s.id, 'hex')

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), target_spu AS ( SELECT id FROM product_spu WHERE id = #{spuId} ), target_hot AS ( SELECT h.sku_id FROM product_hot_sku h INNER JOIN normalized_requested r ON r.id = h.sku_id WHERE h.spu_id = #{spuId} ), deleted AS ( DELETE FROM product_hot_sku h USING target_hot t WHERE h.sku_id = t.sku_id AND h.spu_id = #{spuId} AND EXISTS (SELECT 1 FROM target_spu) RETURNING h.sku_id ) SELECT EXISTS(SELECT 1 FROM target_spu) AS "spuExists", (SELECT COUNT(*) FROM normalized_requested) AS "requestedCount", (SELECT COUNT(*) FROM target_hot) AS "matchedCount", (SELECT COUNT(*) FROM deleted) AS "affectedCount", COALESCE((SELECT jsonb_agg(encode(sku_id, 'hex')) FROM deleted), '[]'::jsonb)::text AS "deletedSkuIdsJson"
